// src/coach.js
var API = "https://generativelanguage.googleapis.com/v1beta/models";
function limparSchema(s) {
  if (Array.isArray(s)) return s.map(limparSchema);
  if (s && typeof s === "object") {
    const o = {};
    for (const [k, v] of Object.entries(s)) if (k !== "additionalProperties") o[k] = limparSchema(v);
    return o;
  }
  return s;
}
var SCHEMA = limparSchema(COACH_SCHEMA);
var Coach = class {
  constructor(settings, setup, docs, leadDocs = []) {
    this.leadDocs = leadDocs;
    this.settings = settings;
    this.setup = setup;
    this.system = [SYSTEM_PROMPT, correcoesOficiais(settings.correcoes), baseDeConhecimento(docs)].filter(Boolean).join("\n\n");
    this.contents = [];
    this.busy = false;
    this.semThinking = false;
    this.semSchema = false;
  }
  body(userText, json) {
    const generationConfig = { maxOutputTokens: 16384 };
    if (json) {
      generationConfig.responseMimeType = "application/json";
      if (!this.semSchema) generationConfig.responseJsonSchema = SCHEMA;
    }
    if (!this.semThinking && this.settings.thinking) {
      generationConfig.thinkingConfig = { thinkingLevel: this.settings.thinking };
    }
    let system = this.system;
    if (json && this.semSchema) system += `

Responda SOMENTE com JSON neste schema:
${JSON.stringify(SCHEMA)}`;
    return {
      systemInstruction: { parts: [{ text: system }] },
      contents: [...this.contents, { role: "user", parts: [{ text: userText }] }],
      generationConfig
    };
  }
  async call(userText, json) {
    const model = this.settings.model || "gemini-3.5-flash";
    for (let tentativa = 0; tentativa < 3; tentativa++) {
      let res;
      try {
        res = await fetch(`${API}/${encodeURIComponent(model)}:generateContent`, {
          method: "POST",
          headers: { "content-type": "application/json", "x-goog-api-key": this.settings.geminiKey },
          body: JSON.stringify(this.body(userText, json))
        });
      } catch {
        await new Promise((r) => setTimeout(r, 1500));
        continue;
      }
      const data = await res.json().catch(() => ({}));
      if (res.ok) return data;
      const msg = data.error?.message || `HTTP ${res.status}`;
      if (res.status === 400 && /thinking/i.test(msg) && !this.semThinking) {
        this.semThinking = true;
        continue;
      }
      if (res.status === 400 && /schema/i.test(msg) && !this.semSchema) {
        this.semSchema = true;
        continue;
      }
      if (res.status === 429 || res.status >= 500) {
        await new Promise((r) => setTimeout(r, 1500));
        continue;
      }
      throw new Error(msg);
    }
    throw new Error("Gemini indispon\xEDvel no momento, tentando de novo na pr\xF3xima an\xE1lise.");
  }
  async send(userText, json) {
    if (this.busy) return null;
    this.busy = true;
    try {
      const data = await this.call(userText, json);
      const cand = data.candidates?.[0];
      if (!cand?.content?.parts) {
        throw new Error(`Gemini n\xE3o respondeu (${cand?.finishReason || data.promptFeedback?.blockReason || "sem conte\xFAdo"}).`);
      }
      this.contents.push({ role: "user", parts: [{ text: userText }] });
      this.contents.push(cand.content);
      this.condensar();
      const text2 = cand.content.parts.filter((p) => p.text && !p.thought).map((p) => p.text).join("");
      return { text: text2, usage: data.usageMetadata };
    } finally {
      this.busy = false;
    }
  }
  // Reunião longa: as análises antigas (JSON grande) incham cada chamada. Mantém as
  // últimas trocas inteiras e junta as antigas num bloco só com a transcrição e os
  // pedidos (nada da conversa se perde), mais a última análise antiga como referência.
  condensar(manter = 6, limite = 14) {
    if (this.contents.length <= limite * 2) return;
    const velhas = this.contents.slice(0, this.contents.length - manter * 2);
    const textoDe = (c) => c.parts.filter((p) => p.text && !p.thought).map((p) => p.text).join("");
    const historico = velhas.filter((c) => c.role === "user").map(textoDe).join("\n\n");
    const ultimaAnalise = textoDe(velhas[velhas.length - 1]);
    this.contents = [
      { role: "user", parts: [{ text: `HIST\xD3RICO DA REUNI\xC3O AT\xC9 AQUI (trocas antigas condensadas):

${historico}` }] },
      { role: "model", parts: [{ text: ultimaAnalise }] },
      ...this.contents.slice(-manter * 2)
    ];
  }
  // newLines: [{speaker, text}] desde a última análise. pedido: pergunta livre do closer.
  async analyze(newLines, pedido, notas = []) {
    const partes = [];
    if (!this.contents.length) partes.push(contextoInicial(this.setup, this.leadDocs));
    partes.push(
      newLines.length ? `TRANSCRI\xC7\xC3O NOVA (desde a \xFAltima an\xE1lise):
${newLines.map((l) => `${l.speaker}: ${l.text}`).join("\n")}` : "TRANSCRI\xC7\xC3O NOVA: (nada novo)"
    );
    partes.push(...notas);
    if (pedido) partes.push(`PEDIDO DO CLOSER: ${pedido}`);
    const res = await this.send(partes.join("\n\n"), true);
    if (!res) return null;
    const t = res.text;
    const jsonText = t.slice(t.indexOf("{"), t.lastIndexOf("}") + 1);
    try {
      return { data: JSON.parse(jsonText), usage: res.usage };
    } catch {
      throw new Error("Resposta da IA veio em formato inesperado.");
    }
  }
  async ata(restante) {
    const partes = [];
    if (!this.contents.length) partes.push(contextoInicial(this.setup, this.leadDocs));
    if (restante.length) {
      partes.push(`TRANSCRI\xC7\xC3O FINAL:
${restante.map((l) => `${l.speaker}: ${l.text}`).join("\n")}`);
    }
    partes.push(PEDIDO_ATA);
    let res = null;
    while (!res) {
      while (this.busy) await new Promise((r) => setTimeout(r, 300));
      res = await this.send(partes.join("\n\n"), false);
    }
    return res.text;
  }
};

// src/md.js
var EV_RE = /(\[(?:INFERÊNCIA|INFERENCIA|VALIDAR|DADO NÃO INFORMADO|DADO NAO INFORMADO|CONTRADIÇÃO DE FONTE|CONTRADICAO DE FONTE)\])/i;
var EV_CLASS = (t) => /INFER/i.test(t) ? "ev-inf" : /VALIDAR/i.test(t) ? "ev-val" : /CONTRADI/i.test(t) ? "ev-con" : "ev-dni";
var NUM_RE = /(R\$\s?\d+(?:[.,]\d+)*(?:\s?(?:mil|milhões|milhão|k)\b)?|\d+(?:[.,]\d+)*(?:\s?(?:%|mil\b|milhões\b|milhão\b|k\b))?)/gi;
function text(node, t, nums = true) {
  t.split(EV_RE).forEach((chunk, j) => {
    if (!chunk) return;
    if (j % 2 === 1) {
      const s = document.createElement("span");
      s.className = `ev ${EV_CLASS(chunk)}`;
      s.textContent = chunk.slice(1, -1);
      node.append(s);
      return;
    }
    if (!nums) {
      node.append(document.createTextNode(chunk));
      return;
    }
    chunk.split(NUM_RE).forEach((part, i) => {
      if (!part) return;
      if (i % 2 === 1) {
        const m = document.createElement("mark");
        m.className = "num";
        m.textContent = part;
        node.append(m);
      } else node.append(document.createTextNode(part));
    });
  });
}
function inline(node, t, nums = true) {
  t.split(/(\*\*[^*]+\*\*)/).forEach((part) => {
    if (/^\*\*[^*]+\*\*$/.test(part)) {
      const b = document.createElement("strong");
      text(b, part.slice(2, -2), nums);
      node.append(b);
    } else if (part) text(node, part, nums);
  });
  return node;
}
var mk = (tag) => document.createElement(tag);
var cells = (line) => line.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
function renderMarkdown(box, md) {
  box.innerHTML = "";
  const lines = (md || "").split("\n");
  let ul = null;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trimEnd();
    if (/^\s*\|.*\|\s*$/.test(line) && /^\s*\|[\s:|-]+\|\s*$/.test(lines[i + 1] || "")) {
      ul = null;
      const wrap = mk("div");
      wrap.style.overflowX = "auto";
      const t = mk("table");
      const tr = mk("tr");
      cells(line).forEach((c) => tr.append(inline(mk("th"), c)));
      const thead = mk("thead");
      thead.append(tr);
      t.append(thead);
      const tb = mk("tbody");
      i += 2;
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) {
        const r = mk("tr");
        cells(lines[i]).forEach((c) => r.append(inline(mk("td"), c)));
        tb.append(r);
        i++;
      }
      i--;
      t.append(tb);
      wrap.append(t);
      box.append(wrap);
      continue;
    }
    let m;
    if (m = line.match(/^(#{1,4})\s+(.*)$/)) {
      ul = null;
      box.append(inline(mk(m[1].length >= 3 ? "h4" : "h3"), m[2], false));
      continue;
    }
    if (/^\s*([-*•]|\d+[.)])\s+/.test(line)) {
      if (!ul) {
        ul = mk("ul");
        box.append(ul);
      }
      ul.append(inline(mk("li"), line.replace(/^\s*([-*•]|\d+[.)])\s+/, "")));
      continue;
    }
    ul = null;
    if (line.trim() && !/^-{3,}$/.test(line.trim())) box.append(inline(mk("p"), line));
  }
}
function followUp(md) {
  const m = (md || "").match(/#+[^\n]*follow[^\n]*\n([\s\S]*?)(?=\n#+\s|$)/i);
  return m ? m[1].trim() : "";
}

